import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testCommonElements() {
        val result = commonTeams(setOf(4215, 1234, 5678), setOf(5678, 9999, 4215))
        Assert.assertEquals(2, result.size)
        Assert.assertTrue(result.contains(4215))
        Assert.assertTrue(result.contains(5678))
    }

    @Test
    fun testNoCommonElements() {
        val result = commonTeams(setOf(4215, 1234), setOf(5678, 9999))
        Assert.assertTrue(result.isEmpty())
    }

    @Test
    fun testAllCommon() {
        val result = commonTeams(setOf(4215, 1234), setOf(4215, 1234))
        Assert.assertEquals(2, result.size)
    }

    @Test
    fun testOneEmptySet() {
        val result = commonTeams(setOf(4215, 1234), emptySet())
        Assert.assertTrue(result.isEmpty())
    }
}
